        { id: "pub_m_em_23_q1", qNum: 1, type: "1m", mark: "1 Mark", topic: "Relations and Functions", q: "If A = {a, b, p}, B = {2, 3}, C = {p, q, r, s}, then n[(A ∪ C) × B] is:<br>(A) 8<br>(B) 20<br>(C) 12<br>(D) 16", ans: "<b>Correct Answer: (C) 12</b><br><b>Explanation:</b> A ∪ C = {a, b, p, q, r, s} ⟹ n(A ∪ C) = 6. n(B) = 2.<br>n[(A ∪ C) × B] = n(A ∪ C) × n(B) = 6 × 2 = <b>12</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q2", qNum: 2, type: "1m", mark: "1 Mark", topic: "Numbers and Sequences", q: "According to Euclid's division lemma, for any two positive integers a and b, there exist unique integers q and r such that a = bq + r, where r satisfies:<br>(A) 0 < r < b<br>(B) 0 ≤ r < b<br>(C) 0 < r ≤ b<br>(D) 0 ≤ r ≤ b", ans: "<b>Correct Answer: (B) 0 ≤ r < b</b><br><b>Explanation:</b> The remainder r in Euclid's division lemma is always non-negative and strictly less than the divisor b.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q3", qNum: 3, type: "1m", mark: "1 Mark", topic: "Algebra", q: "The system of linear equations 3x - y = 2 and 6x - 2y = 4 has:<br>(A) unique solution<br>(B) two solutions<br>(C) infinitely many solutions<br>(D) no solution", ans: "<b>Correct Answer: (C) infinitely many solutions</b><br><b>Explanation:</b> Here a₁/a₂ = 3/6 = 1/2, b₁/b₂ = -1/-2 = 1/2, c₁/c₂ = 2/4 = 1/2. Since a₁/a₂ = b₁/b₂ = c₁/c₂, the lines are coincident and possess infinitely many solutions.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q4", qNum: 4, type: "1m", mark: "1 Mark", topic: "Geometry", q: "The ratio of the areas of two similar triangles is equal to the ratio of:<br>(A) their corresponding sides<br>(B) squares of their corresponding sides<br>(C) cubes of their corresponding sides<br>(D) their perimeters", ans: "<b>Correct Answer: (B) squares of their corresponding sides</b><br><b>Explanation:</b> By Area Theorem of similar triangles, the ratio of areas is proportional to the squares of corresponding sides.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q5", qNum: 5, type: "1m", mark: "1 Mark", topic: "Coordinate Geometry", q: "The straight line x = 11 is:<br>(A) parallel to X-axis<br>(B) parallel to Y-axis<br>(C) passing through origin<br>(D) passing through (0, 11)", ans: "<b>Correct Answer: (B) parallel to Y-axis</b><br><b>Explanation:</b> The equation x = c represents a straight line parallel to the Y-axis.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q6", qNum: 6, type: "1m", mark: "1 Mark", topic: "Trigonometry", q: "If tan θ = cot θ, then the value of θ (0° ≤ θ ≤ 90°) is:<br>(A) 30°<br>(B) 45°<br>(C) 60°<br>(D) 90°", ans: "<b>Correct Answer: (B) 45°</b><br><b>Explanation:</b> tan θ = cot θ ⟹ tan² θ = 1 ⟹ tan θ = 1 ⟹ θ = <b>45°</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q7", qNum: 7, type: "1m", mark: "1 Mark", topic: "Mensuration", q: "If the sum of outer and inner radii of a hollow cylinder is 14 cm and thickness is 4 cm, then its outer radius is:<br>(A) 9 cm<br>(B) 10 cm<br>(C) 8 cm<br>(D) 7 cm", ans: "<b>Correct Answer: (A) 9 cm</b><br><b>Explanation:</b> R + r = 14 and R - r = 4. Adding both gives 2R = 18 ⟹ R = <b>9 cm</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q8", qNum: 8, type: "1m", mark: "1 Mark", topic: "Statistics", q: "The variance of the first 10 natural numbers is:<br>(A) 8.25<br>(B) 6.5<br>(C) 8.5<br>(D) 9.25", ans: "<b>Correct Answer: (A) 8.25</b><br><b>Explanation:</b> Variance σ² = (n² - 1) / 12 = (10² - 1) / 12 = 99 / 12 = <b>8.25</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q9", qNum: 9, type: "1m", mark: "1 Mark", topic: "Probability", q: "When a fair coin is tossed thrice, the number of sample points in the sample space is:<br>(A) 6<br>(B) 8<br>(C) 9<br>(D) 12", ans: "<b>Correct Answer: (B) 8</b><br><b>Explanation:</b> n(S) = 2³ = <b>8</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q10", qNum: 10, type: "1m", mark: "1 Mark", topic: "Arithmetic Progression", q: "The number of terms in the sequence 3, 6, 9, ... 111 is:<br>(A) 36<br>(B) 37<br>(C) 38<br>(D) 39", ans: "<b>Correct Answer: (B) 37</b><br><b>Explanation:</b> n = [(l - a) / d] + 1 = [(111 - 3) / 3] + 1 = (108 / 3) + 1 = 36 + 1 = <b>37</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q11", qNum: 11, type: "1m", mark: "1 Mark", topic: "Matrices", q: "If A = [aᵢⱼ]₂ₓ₂ and aᵢⱼ = i + j, then matrix A is:<br>(A) [[2, 3], [3, 4]]<br>(B) [[1, 2], [3, 4]]<br>(C) [[2, 3], [4, 5]]<br>(D) [[1, 1], [2, 2]]", ans: "<b>Correct Answer: (A) [[2, 3], [3, 4]]</b><br><b>Explanation:</b> a₁₁=2, a₁₂=3, a₂₁=3, a₂₂=4.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q12", qNum: 12, type: "1m", mark: "1 Mark", topic: "Straight Lines", q: "The equation of a straight line passing through the origin is of the form:<br>(A) y = mx + c<br>(B) y = mx<br>(C) x = c<br>(D) y = c", ans: "<b>Correct Answer: (B) y = mx</b><br><b>Explanation:</b> Since y-intercept c = 0, y = mx represents a line through origin.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q13", qNum: 13, type: "1m", mark: "1 Mark", topic: "Mensuration", q: "If the curved surface area of a solid sphere is 36π sq.cm, then its radius is:<br>(A) 3 cm<br>(B) 6 cm<br>(C) 9 cm<br>(D) 4 cm", ans: "<b>Correct Answer: (A) 3 cm</b><br><b>Explanation:</b> 4πr² = 36π ⟹ r² = 9 ⟹ r = <b>3 cm</b>.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_m_em_23_q14", qNum: 14, type: "1m", mark: "1 Mark", topic: "Composite Functions", q: "If f = {(1, 2), (2, 3), (3, 4)} and g = {(2, 5), (3, 6), (4, 7)}, then gof is:<br>(A) {(1, 5), (2, 6), (3, 7)}<br>(B) {(2, 1), (3, 2), (4, 3)}<br>(C) {(1, 2), (2, 3)}<br>(D) not defined", ans: "<b>Correct Answer: (A) {(1, 5), (2, 6), (3, 7)}</b><br><b>Explanation:</b> g(f(1)) = g(2) = 5; g(f(2)) = g(3) = 6; g(f(3)) = g(4) = 7.", markingScheme: "Option and answer: 1 Mark", isCompulsory: false }
