      questions: [
        { id: "pub_sci_em_23_q13", qNum: 13, type: "2m", mark: "2 Marks", topic: "Laws of Motion", q: "State Newton's Second Law of Motion.", ans: "<b>Statement:</b> The force acting on a body is directly proportional to the rate of change of linear momentum of the body and the change in momentum takes place in the direction of the force. <b>F = ma</b>.", markingScheme: "Statement: 1 Mark, Formula: 1 Mark = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q14", qNum: 14, type: "2m", mark: "2 Marks", topic: "Optics", q: "Why do stars twinkle?", ans: "Stars twinkle due to atmospheric refraction of starlight. The physical conditions of earth's atmosphere change continuously, altering refractive index, causing apparent position and brightness of the star to fluctuate.", markingScheme: "Atmospheric refraction explanation: 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q15", qNum: 15, type: "2m", mark: "2 Marks", topic: "Thermal Physics", q: "State Boyle's Law.", ans: "<b>Boyle's Law:</b> When the temperature of a gas is kept constant, the volume of a fixed mass of gas is inversely proportional to its pressure.<br><b>P ∝ 1/V or PV = Constant</b>.", markingScheme: "Statement: 1 Mark, Equation: 1 Mark = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q16", qNum: 16, type: "2m", mark: "2 Marks", topic: "Reproduction", q: "Differentiate between Menarche and Menopause.", ans: "1. <b>Menarche:</b> The first occurrence of menstruation at puberty in girls (around age 11–13).<br>2. <b>Menopause:</b> The permanent cessation of menstruation and ovulation in women (around age 45–50).", markingScheme: "Menarche: 1 Mark, Menopause: 1 Mark = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q17", qNum: 17, type: "2m", mark: "2 Marks", topic: "Avogadro's Hypothesis", q: "State Avogadro's Hypothesis.", ans: "<b>Avogadro's Law:</b> Equal volumes of all gases under the same conditions of temperature and pressure contain equal number of molecules. <b>V ∝ n</b>.", markingScheme: "Statement: 1M, Equation: 1M = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q18", qNum: 18, type: "2m", mark: "2 Marks", topic: "Chemical Reactions", q: "What is rust? Give its chemical formula.", ans: "When iron is exposed to moist air, it reacts with oxygen to form hydrated ferric oxide, which is called rust.<br><b>Chemical formula: Fe₂O₃ · xH₂O</b>.", markingScheme: "Definition: 1 Mark, Formula: 1 Mark = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q19", qNum: 19, type: "2m", mark: "2 Marks", topic: "Nervous System", q: "Name the three major divisions of human brain.", ans: "1. <b>Forebrain:</b> Cerebrum, Thalamus, Hypothalamus.<br>2. <b>Midbrain:</b> Visual and auditory reflex centres.<br>3. <b>Hindbrain:</b> Cerebellum, Pons, Medulla oblongata.", markingScheme: "3 divisions with parts: 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q20", qNum: 20, type: "2m", mark: "2 Marks", topic: "Transpiration", q: "What is transpiration pull?", ans: "The suction force created by the evaporation of water through the stomata of leaves, which pulls water column upwards from roots through xylem, is called transpiration pull.", markingScheme: "Clear definition: 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q21", qNum: 21, type: "2m", mark: "2 Marks", topic: "Genetics", q: "What are allosomes?", ans: "Chromosomes responsible for determining the sex of an individual are called allosomes or sex chromosomes (e.g. X and Y chromosomes; 23rd pair in humans).", markingScheme: "Definition: 1 Mark, Example: 1 Mark = 2 Marks", isCompulsory: false },
        { id: "pub_sci_em_23_q22", qNum: 22, type: "2m", mark: "2 Marks", topic: "Electricity / Compulsory", q: "<b>[COMPULSORY QUESTION]</b><br>A current of 2 A passes through a wire of resistance 5 Ω for 5 seconds. Calculate the heat energy produced in the wire.", ans: "<b>Solution (Question 22 - Compulsory Question):</b><br>Given: Current I = 2 A, Resistance R = 5 Ω, Time t = 5 s.<br>By Joule's law of heating: H = I² · R · t<br>H = (2)² × 5 × 5 = 4 × 25 = <b>100 Joules (100 J)</b>.<br><b>Answer: Heat energy produced = 100 J</b>.", markingScheme: "Formula H = I²Rt: 1 Mark, Calculation & Unit: 1 Mark = 2 Marks", isCompulsory: true }
      ]
