        { id: "pub_sci_em_22_q29", qNum: 29, type: "4m", mark: "4 Marks", topic: "Flower Structure", q: "Explain the parts of a gynoecium (pistil) in a flower.", ans: "Gynoecium is the female reproductive part consisting of carpels:<br>1. <b>Stigma:</b> Sticky terminal part where pollen grains germinate.<br>2. <b>Style:</b> Slender column connecting stigma to ovary through which pollen tube grows.<br>3. <b>Ovary:</b> Basal swollen part containing ovules. Following fertilization, ovary develops into fruit and ovules into seeds.", markingScheme: "3 parts detailed description: 4 Marks", isCompulsory: false },
        { id: "pub_sci_em_22_q30", qNum: 30, type: "4m", mark: "4 Marks", topic: "Mendel's Laws", q: "State Mendel's laws of inheritance.", ans: "1. <b>Law of Dominance:</b> In a monohybrid cross, only the dominant allele expresses itself in the heterozygous condition.<br>2. <b>Law of Segregation:</b> The two alleles of a gene separate during gamete formation so that each gamete carries only one allele.<br>3. <b>Law of Independent Assortment:</b> When two pairs of traits are crossed, the segregation of alleles of one pair is independent of the other pair.", markingScheme: "3 laws: 4 Marks", isCompulsory: false },
        { id: "pub_sci_em_22_q31", qNum: 31, type: "4m", mark: "4 Marks", topic: "Effects of Tobacco", q: "What are the health hazards caused by tobacco smoking?", ans: "1. Nicotine stimulates adrenal gland, increasing adrenaline, raising blood pressure and risk of heart attacks.<br>2. Carbon monoxide reduces oxygen carrying capacity of haemoglobin.<br>3. Tar settles in lungs, paralyzing cilia and causing emphysema, bronchitis and lung cancer.<br>4. Causes oral cavity, throat, and bladder cancers.", markingScheme: "4 hazards: 4 Marks", isCompulsory: false },
        { id: "pub_sci_em_22_q32", qNum: 32, type: "4m", mark: "4 Marks", topic: "Electric Heating / Compulsory", q: "<b>[COMPULSORY QUESTION]</b><br>100 J of heat is produced each second in a 4 Ω resistor. Find the potential difference across the resistor.", ans: "<b>Solution (Question 32 - Compulsory Question):</b><br>Given: Heat H = 100 J, Time t = 1 s, Resistance R = 4 Ω.<br>Formula: H = (V² / R) · t<br>V² = (H × R) / t = (100 × 4) / 1 = 400<br>V = √400 = <b>20 Volts (20 V)</b>.<br><b>Answer: Potential difference across resistor = 20 V</b>.", markingScheme: "Formula: 1 Mark, V² = 400: 2 Marks, Final answer 20 V: 1 Mark = 4 Marks", isCompulsory: true }
