        { id: "pub_soc_em_23_q8", qNum: 8, type: "1m", mark: "1 Mark", topic: "Geography", q: "Which city is known as the 'Manchester of India'?<br>(A) Chennai<br>(B) Mumbai<br>(C) Ahmedabad<br>(D) Coimbatore", ans: "<b>Correct Answer: (B) Mumbai</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q9", qNum: 9, type: "1m", mark: "1 Mark", topic: "Civics", q: "Who is the Guardian of the Indian Constitution?<br>(A) President<br>(B) Parliament<br>(C) Supreme Court<br>(D) Prime Minister", ans: "<b>Correct Answer: (C) Supreme Court</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q10", qNum: 10, type: "1m", mark: "1 Mark", topic: "Civics", q: "The Governor of a State is appointed by the:<br>(A) Chief Minister<br>(B) Prime Minister<br>(C) President<br>(D) Chief Justice of High Court", ans: "<b>Correct Answer: (C) President</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q11", qNum: 11, type: "1m", mark: "1 Mark", topic: "Civics", q: "Panchsheel treaty was signed in the year:<br>(A) 1950<br>(B) 1954<br>(C) 1962<br>(D) 1971", ans: "<b>Correct Answer: (B) 1954 (Nehru and Zhou Enlai)</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q12", qNum: 12, type: "1m", mark: "1 Mark", topic: "Economics", q: "Gross Domestic Product (GDP) measures:<br>(A) Production of goods only<br>(B) Production of services only<br>(C) Market value of all final goods and services produced in a country in a year<br>(D) Net exports", ans: "<b>Correct Answer: (C) Market value of all final goods and services produced in a country in a year</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q13", qNum: 13, type: "1m", mark: "1 Mark", topic: "Economics", q: "Headquarters of the World Trade Organisation (WTO) is in:<br>(A) New York<br>(B) Geneva<br>(C) London<br>(D) Paris", ans: "<b>Correct Answer: (B) Geneva (Switzerland)</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false },
        { id: "pub_soc_em_23_q14", qNum: 14, type: "1m", mark: "1 Mark", topic: "Economics", q: "Goods and Services Tax (GST) came into effect in India on:<br>(A) 1 July 2017<br>(B) 1 April 2017<br>(C) 1 January 2018<br>(D) 8 November 2016", ans: "<b>Correct Answer: (A) 1 July 2017</b>", markingScheme: "Option and answer: 1 Mark", isCompulsory: false }
