        { id: "pub_soc_em_23_q43", qNum: 43, type: "8m", mark: "8 Marks", topic: "History", q: "(a) Account for the causes and consequences of the Vellore Revolt of 1806.<br><b>(OR)</b><br>(b) Discuss the causes and outcomes of the Great Revolt of 1857.", ans: "<b>(a) Vellore Revolt (1806):</b><br>1. <b>Causes:</b> Strict dress regulations introduced by Gen. Agnew, round turban, removal of caste marks and beards.<br>2. <b>Outbreak:</b> Indian sepoys revolted on 10 July 1806, killed Col. Fancourt, and hoisted Tipu Sultan's flag.<br>3. <b>Suppression:</b> Col. Gillespie arrived from Arcot and crushed the uprising ruthlessly.<br>4. <b>Consequences:</b> New dress code withdrawn; Tipu's family exiled to Calcutta; Lord William Bentinck recalled.", markingScheme: "Causes: 3M, Outbreak: 3M, Outcome: 2M = 8 Marks", isCompulsory: false },
        { id: "pub_soc_em_23_q44", qNum: 44, type: "8m", mark: "8 Marks", topic: "India Map", q: "Mark the following 8 geographical locations on the outline map of India:<br>(i) Himalayas (ii) River Ganga (iii) Coromandel Coast (iv) Mumbai (v) Black soil region (vi) Kaziranga National Park (vii) Chennai (viii) Tuticorin Port.", ans: "<b>Locations on Map:</b><br>1. Himalayas: Northern mountain arc.<br>2. River Ganga: Originates in Uttarakhand and drains into Bay of Bengal.<br>3. Coromandel Coast: East coast of Tamil Nadu.<br>4. Mumbai: West coast in Maharashtra.<br>5. Black soil: Deccan plateau (Maharashtra/Gujarat).<br>6. Kaziranga: Assam.<br>7. Chennai: Capital of Tamil Nadu on east coast.<br>8. Tuticorin Port: Southern Tamil Nadu coast.", markingScheme: "8 correct locations: 8 × 1 = 8 Marks", isCompulsory: false }
